ICON_HEAD = """import type { ReactNode, Ref } from "react";

export interface IconProps {
    height?: number | string;
    width?: number | string;
    className?: string;
    /** for callers that need to find the button an icon was put in */
    innerRef?: Ref<SVGSVGElement>;
}

export type IconComponent = (props: IconProps & Record<string, any>) => ReactNode;

/**
 * One filled glyph on a 24 unit grid, drawn in the colour of whatever it sits in.
 *
 * All of them are built the same way so they sit at the same weight beside each other and
 * beside the ones Discord draws, in a menu, on a button or in a heading.
 */
const icon = (d: string): IconComponent => function Icon({ height = 20, width = 20, className, innerRef }) {
    return (
        <svg ref={innerRef} aria-hidden viewBox="0 0 24 24" height={height} width={width} className={className}>
            <path fill="currentColor" d={d} />
        </svg>
    );
};

"""


def icons(names):
    out = HEAD + ICON_HEAD
    for n in sorted(set(names) | {"Lock"}):
        out += 'export const %sIcon = icon("%s");\n' % (n, ICONS[n])
    return out


if __name__ == "__main__":
    root, folder, prefix, kinds, *names = sys.argv[1:]
    here = os.path.dirname(os.path.abspath(__file__))
    d = os.path.join(root, folder)

    def put(name, text):
        open(os.path.join(d, name), "w", encoding="utf-8", newline="\n").write(text)

    def tpl(name):
        return open(os.path.join(here, name), encoding="utf-8").read().replace("__PREFIX__", prefix)

    put("icons.tsx", icons(names))
    if "ui" in kinds:
        put("ui.tsx", tpl("ui.tsx.tpl"))
    css = []
    if "ui" in kinds:
        css.append(tpl("ui.css.tpl"))
    if "form" in kinds:
        css.append(tpl("form.css.tpl"))
    put("shared.css", "\n".join(css))
    print(folder, "ok")
